class Solution {
    unordered_map<int,TreeNode*> roots;
    bool validate(TreeNode* node,long long low,long long high){
        if(!node)return true;
        if(node->val<=low||node->val>=high)return false;
        if(!node->left&&!node->right&&roots.count(node->val)&&roots[node->val]!=node){
            TreeNode* merged=roots[node->val];
            roots.erase(node->val);
            node->left=merged->left;
            node->right=merged->right;
        }
        return validate(node->left,low,node->val)&&validate(node->right,node->val,high);
    }
    public: TreeNode* canMerge(vector<TreeNode*>& trees){
        unordered_set<int> leaves;
        for(TreeNode* tree:trees){
            roots[tree->val]=tree;
            if(tree->left)leaves.insert(tree->left->val);
            if(tree->right)leaves.insert(tree->right->val);
        }
        TreeNode* root=nullptr;
        for(TreeNode* tree:trees)if(!leaves.count(tree->val)){
            if(root)return nullptr;
            root=tree;
        }
        if(!root||!validate(root,LLONG_MIN,LLONG_MAX)||roots.size()!=1)return nullptr;
        return root;
    }
};
